-- User-authorized support contacts and platform clarification; no progress reset.
begin;
select pg_advisory_xact_lock(782541);
do $release$
declare payload jsonb:=$payload${"units":[{"id":"support-boundaries","body_hash":"f1a245c321e6b1c8891ea0081ea23d16","mk_hash":"c0ab539cc61c643c2a0da800d93c5378","revision":2},{"id":"support-service","body_hash":"0329cb73d8c989160e54e9ade8e721f3","mk_hash":"8ee0760066dee0aeb726f61a9e1884a9","revision":2}],"edits":[{"unit_id":"support-boundaries","field":"body","before":"contact Henry, Toby, or Rose","after":"contact Stefan"},{"unit_id":"support-boundaries","field":"body_mk","before":"контактирај ги Henry, Toby или Rose","after":"контактирај го Стефан"},{"unit_id":"support-service","field":"body","before":"Notify management of this","after":"Notify Stefan of this"},{"unit_id":"support-service","field":"body_mk","before":"Извести го менаџментот за ова","after":"Извести го Стефан за ова"},{"unit_id":"support-boundaries","field":"body","before":"\n1. Are you AI?\n","after":"\n1. Are you AI? (Fanvue only)\n"},{"unit_id":"support-boundaries","field":"body_mk","before":"\n1. Дали си AI?\n","after":"\n1. Дали си AI? (Само за Fanvue)\n"},{"unit_id":"support-boundaries","field":"body","before":"\n## 1. Are you AI?\n","after":"\n## 1. Are you AI? (Fanvue only)\n\n**Fanvue only:** At EVZON, OnlyFans work is with real models. Around 90% of our Fanvue assignments are with AI models.\n"},{"unit_id":"support-boundaries","field":"body_mk","before":"\n## 1. Дали си AI?\n","after":"\n## 1. Дали си AI? (Само за Fanvue)\n\n**Само за Fanvue:** Во EVZON, на OnlyFans работиме со вистински модели. Околу 90% од нашите ангажмани на Fanvue се со AI-модели.\n"}],"questions":[{"before":{"id":"f-25","test_key":"final","unit_id":"support-service","prompt":{"en":"A fan threatens a chargeback while demanding a refund. Who needs to be informed under the support guide?","mk":"Фан се заканува со chargeback додека бара поврат на пари. Кој треба да биде известен според водичот за поддршка?"},"options":[{"id":"a","en":"Notify management about the threat.","mk":"Извести го менаџментот за заканата."},{"id":"b","en":"Promise a refund yourself without informing management.","mk":"Сам вети поврат без да го известиш менаџментот."},{"id":"c","en":"Ignore the threat if the fan has purchased before.","mk":"Игнорирај ја заканата ако фанот претходно купувал."},{"id":"d","en":"Move the complaint to a personal messaging account.","mk":"Префрли ја поплаката на лична сметка за пораки."}],"correct":"a","source_anchor":"(Notify management of this).","explanation":{"en":"The chargeback/refund-threat section explicitly instructs chatters to notify management.","mk":"Делот за закани со chargeback или поврат изречно бара четерите да го известат менаџментот."}},"after":{"id":"f-25","test_key":"final","unit_id":"support-service","prompt":{"en":"A fan threatens a chargeback while demanding a refund. Who needs to be informed under the support guide?","mk":"Фан се заканува со chargeback додека бара поврат на пари. Кој треба да биде известен според водичот за поддршка?"},"options":[{"id":"a","en":"Notify Stefan about the threat.","mk":"Извести го Стефан за заканата."},{"id":"b","en":"Promise a refund yourself without informing Stefan.","mk":"Сам вети поврат без да го известиш Стефан."},{"id":"c","en":"Ignore the threat if the fan has purchased before.","mk":"Игнорирај ја заканата ако фанот претходно купувал."},{"id":"d","en":"Move the complaint to a personal messaging account.","mk":"Префрли ја поплаката на лична сметка за пораки."}],"correct":"a","source_anchor":"(Notify Stefan of this).","explanation":{"en":"The chargeback/refund-threat section explicitly instructs chatters to notify Stefan.","mk":"Делот за закани со chargeback или поврат изречно бара четерите да го известат Стефан."}}},{"before":{"id":"p4-03","test_key":"practice-4","unit_id":"support-boundaries","prompt":{"en":"You are unsure whether a difficult request is allowed. What should happen before you respond further?","mk":"Не си сигурен дали тешко барање е дозволено. Што треба да се случи пред да продолжиш да одговараш?"},"options":[{"id":"a","en":"Respond based only on what another account once did.","mk":"Одговори само според тоа што некогаш направил друг профил."},{"id":"b","en":"Pause and contact the support contacts identified in the guide.","mk":"Застани и контактирај ги лицата за поддршка наведени во водичот."},{"id":"c","en":"Agree provisionally so the fan stays interested.","mk":"Привремено согласи се за фанот да остане заинтересиран."},{"id":"d","en":"Let the fan decide which rules apply.","mk":"Остави фанот да одлучи кои правила важат."}],"correct":"b","source_anchor":"If you are unsure, pause the conversation and contact Henry, Toby, or Rose before responding further.","explanation":{"en":"The guide explicitly tells an unsure chatter to pause and contact the named support contacts before continuing.","mk":"Водичот изречно му кажува на чатерот што не е сигурен да застане и да ги контактира наведените лица за поддршка пред да продолжи."}},"after":{"id":"p4-03","test_key":"practice-4","unit_id":"support-boundaries","prompt":{"en":"You are unsure whether a difficult request is allowed. What should happen before you respond further?","mk":"Не си сигурен дали тешко барање е дозволено. Што треба да се случи пред да продолжиш да одговараш?"},"options":[{"id":"a","en":"Respond based only on what another account once did.","mk":"Одговори само според тоа што некогаш направил друг профил."},{"id":"b","en":"Pause and contact Stefan before continuing.","mk":"Застани и контактирај го Стефан пред да продолжиш."},{"id":"c","en":"Agree provisionally so the fan stays interested.","mk":"Привремено согласи се за фанот да остане заинтересиран."},{"id":"d","en":"Let the fan decide which rules apply.","mk":"Остави фанот да одлучи кои правила важат."}],"correct":"b","source_anchor":"If you are unsure, pause the conversation and contact Stefan before responding further.","explanation":{"en":"The guide explicitly tells an unsure chatter to pause and contact Stefan before continuing.","mk":"Водичот изречно му кажува на чатерот што не е сигурен да застане и да го контактира Стефан пред да продолжи."}}},{"before":{"id":"p4-04","test_key":"practice-4","unit_id":"support-service","prompt":{"en":"A fan threatens a chargeback or demands a refund. Which internal action is explicitly required?","mk":"Фан се заканува со поврат преку банка или бара рефундација. Која внатрешна постапка е изречно потребна?"},"options":[{"id":"a","en":"Notify management.","mk":"Извести го менаџментот."},{"id":"b","en":"Handle it without telling anyone.","mk":"Решавај го без да известиш никого."},{"id":"c","en":"Promise a refund without checking with management.","mk":"Вети рефундација без проверка со менаџментот."},{"id":"d","en":"Delete the conversation before reporting it.","mk":"Избриши го разговорот пред да го пријавиш."}],"correct":"a","source_anchor":"Notify management of this","explanation":{"en":"The chargeback and refund section explicitly instructs the chatter to notify management.","mk":"Делот за поврат преку банка и рефундација изречно му наложува на чатерот да го извести менаџментот."}},"after":{"id":"p4-04","test_key":"practice-4","unit_id":"support-service","prompt":{"en":"A fan threatens a chargeback or demands a refund. Which internal action is explicitly required?","mk":"Фан се заканува со поврат преку банка или бара рефундација. Која внатрешна постапка е изречно потребна?"},"options":[{"id":"a","en":"Notify Stefan.","mk":"Извести го Стефан."},{"id":"b","en":"Handle it without telling anyone.","mk":"Решавај го без да известиш никого."},{"id":"c","en":"Promise a refund without checking with Stefan.","mk":"Вети рефундација без проверка со Стефан."},{"id":"d","en":"Delete the conversation before reporting it.","mk":"Избриши го разговорот пред да го пријавиш."}],"correct":"a","source_anchor":"Notify Stefan of this","explanation":{"en":"The chargeback and refund section explicitly instructs the chatter to notify Stefan.","mk":"Делот за поврат преку банка и рефундација изречно му наложува на чатерот да го извести Стефан."}}}]}$payload$::jsonb; item jsonb; current_text text; u evzon_private.training_units; q evzon_private.exam_questions;
begin
 for item in select * from jsonb_array_elements(payload->'units') loop
  select * into u from evzon_private.training_units where id=item->>'id' for update;
  if u.id is null or md5(u.body)<>item->>'body_hash' or md5(u.body_mk)<>item->>'mk_hash' or u.revision<>(item->>'revision')::integer then
   raise exception 'Guide changed since review; no changes applied';
  end if;
 end loop;
 for item in select * from jsonb_array_elements(payload->'questions') loop
  select * into q from evzon_private.exam_questions where id=item->'before'->>'id' for update;
  if q.id is null or to_jsonb(q) is distinct from item->'before' then raise exception 'Question changed since review; no changes applied';end if;
 end loop;
 for item in select * from jsonb_array_elements(payload->'edits') loop
  select case when item->>'field'='body' then body when item->>'field'='body_mk' then body_mk else null end into current_text from evzon_private.training_units where id=item->>'unit_id';
  if current_text is null or length(item->>'before')=0 or (length(current_text)-length(replace(current_text,item->>'before','')))/length(item->>'before')<>1 then raise exception 'Expected guide passage not found exactly once';end if;
  update evzon_private.training_units set
   body=case when item->>'field'='body' then replace(body,item->>'before',item->>'after') else body end,
   body_mk=case when item->>'field'='body_mk' then replace(body_mk,item->>'before',item->>'after') else body_mk end,
   updated_at=now() where id=item->>'unit_id';
 end loop;
 for item in select * from jsonb_array_elements(payload->'questions') loop
  update evzon_private.exam_questions set options=item->'after'->'options',source_anchor=item->'after'->>'source_anchor',explanation=item->'after'->'explanation' where id=item->'after'->>'id';
 end loop;
 if exists(select 1 from evzon_private.exam_questions eq join evzon_private.training_units tu on tu.id=eq.unit_id where strpos(tu.body,eq.source_anchor)=0) then raise exception 'A question lost its guide reference; no changes applied';end if;
 if exists(select 1 from evzon_private.training_units where concat_ws(' ',body,body_mk)~*'Henry|Toby|Rose|Хенри|Тоби|Роуз') then raise exception 'An old support contact remains';end if;
end $release$;
commit;
select 'Guide clarifications and three related questions updated; study progress unchanged.' as result;
